INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "后梁徙康怀贞为永平节度使、镇长安。", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p005·原文件第16行", "note": "原文：帝以岐人数为寇，二月，甲戌，徙感化节度使康怀英为永平节度使，镇长安。；核对说明：原文此时作康怀英，但本段明示其即康怀贞，复用旧主体UUID；“数为寇”未给具体战次数。", "status": "draft", "id": "7088c8a3-7013-546b-a280-57f68a800980", "subject_id": "be8e602b-56d9-562b-ad65-5090e1712ba2", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "914年二月甲戌", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p005·原文件第16行", "note": "原文：帝以岐人数为寇，二月，甲戌，徙感化节度使康怀英为永平节度使，镇长安。；核对说明：沿主书段落次序；干支日未换算公历日。", "status": "draft", "id": "030b3e35-c715-556e-a026-6294ad5d80f6", "subject_id": "be8e602b-56d9-562b-ad65-5090e1712ba2", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱友贞：因岐军屡犯而调整西部军镇的梁帝。", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p005·原文件第16行", "note": "原文：帝以岐人数为寇，二月，甲戌，徙感化节度使康怀英为永平节度使，镇长安。；核对说明：只据本段确认身份；繁简字形用于匹配，原文仍保持底本原字。", "status": "draft", "id": "dd43a917-76c9-5a55-97d0-be493ad8d7b9", "subject_id": "592627e4-8841-5cca-a79b-782c37765037", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱友贞：因岐军屡犯而调整西部军镇的梁帝。", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p005·原文件第16行", "note": "原文：帝以岐人数为寇，二月，甲戌，徙感化节度使康怀英为永平节度使，镇长安。；核对说明：参与身份依据本段措辞，不因同场出现推定其他关系。", "status": "draft", "id": "96057f94-afa0-529e-8164-8e747ed544a8", "subject_id": "ca623022-41db-5cc8-b956-6aced48c80ef", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记康怀贞：以康怀英之名由感化节度使改镇永平、长安。", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p005·原文件第16行", "note": "原文：帝以岐人数为寇，二月，甲戌，徙感化节度使康怀英为永平节度使，镇长安。；核对说明：只据本段确认身份；繁简字形用于匹配，原文仍保持底本原字。", "status": "draft", "id": "b868d6fe-7803-5a46-a823-808142fc2580", "subject_id": "707b355e-351f-54c8-9f94-0c4e96103a1d", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "康怀贞：以康怀英之名由感化节度使改镇永平、长安。", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p005·原文件第16行", "note": "原文：帝以岐人数为寇，二月，甲戌，徙感化节度使康怀英为永平节度使，镇长安。；核对说明：参与身份依据本段措辞，不因同场出现推定其他关系。", "status": "draft", "id": "31cbeba7-0f67-5e5b-b736-4c97b32a4c04", "subject_id": "3af333fd-55e1-5132-a9f1-e1f9b28d334a", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》卷八亦记二月甲戌任康怀英永平军节度使。", "citation": "《旧五代史》卷八，段落 jiu-wudaishi-205deb4a7860-p000360；EPUB电子本，纸本及异文待核", "note": "原文：二月甲戌，以感化軍節度使、華商等州觀察使、檢校太傅、同平章事、太原郡開國公康懷英為大安尹，充永平軍節度使，大安金棣等州觀察處置使。；核对说明：旧书补大安尹等衔；主书“镇长安”与旧书官号不强行互换。", "status": "draft", "id": "8c36cf52-fcc2-584a-b6d9-c886b429f5fc", "subject_id": "be8e602b-56d9-562b-ad65-5090e1712ba2", "source_id": "da7c97e6-fd3d-5cee-a746-64fca0fbc4fa"}, {"subject_table": "event", "field_path": "description", "claim_text": "康怀贞避后梁帝名改名康怀英。", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p005·原文件第16行", "note": "原文：怀英即怀贞也，避帝名改焉。；核对说明：主书明言同一人，改名原因是避帝名；不将名字变化直接定在本段甲戌。", "status": "draft", "id": "bfe1060c-7159-5d2c-91b1-0cb477bfc987", "subject_id": "6712e64f-2c72-5e4e-89bd-b973d7936872", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "朱友贞即位后、914年二月甲戌前后；改名确日未载", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p005·原文件第16行", "note": "原文：怀英即怀贞也，避帝名改焉。；核对说明：段内追叙，确年待考。", "status": "draft", "id": "1b5bc4ee-ad7c-5177-bda0-36e57014222b", "subject_id": "6712e64f-2c72-5e4e-89bd-b973d7936872", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "康怀贞：原名康怀贞，避梁帝名而改康怀英。", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p005·原文件第16行", "note": "原文：怀英即怀贞也，避帝名改焉。；核对说明：参与身份依据本段措辞，不因同场出现推定其他关系。", "status": "draft", "id": "06511fd9-d48a-5a36-a419-27284dac0c63", "subject_id": "619765f6-0ffa-5591-89ee-38a37022cdb0", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "person", "field_path": "aliases", "claim_text": "康怀贞又名康怀英；避后梁末帝名改称怀英。", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p005·原文件第16行", "note": "原文：怀英即怀贞也，避帝名改焉。；核对说明：两种名字归入康怀贞稳定主体；原书不同年代的署名保持原字。", "status": "draft", "id": "63e3746a-239d-55e0-8887-f6e4e87167ad", "subject_id": "707b355e-351f-54c8-9f94-0c4e96103a1d", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "person", "field_path": "aliases", "claim_text": "《旧五代史》卷二十三亦明确记康怀英本名怀贞。", "citation": "《旧五代史》卷二十三，段落 jiu-wudaishi-205deb4a7860-p000777；EPUB电子本，纸本及异文待核", "note": "原文：康懷英，兗州人也。本名懷貞，避末帝御名，故改之。；核对说明：旧书传记与通鉴本段一致；避讳关系在两书明示，非仅凭字形相似推断。", "status": "draft", "id": "f53a69ca-801e-56ee-aece-366da8648e3e", "subject_id": "707b355e-351f-54c8-9f94-0c4e96103a1d", "source_id": "fcbd5799-8cd1-5c2f-bf0c-0096cd5158af"}, {"subject_table": "event", "field_path": "description", "claim_text": "前蜀迁镇江军治于夔州。", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p006·原文件第17行", "note": "原文：夏，四月，丙子，蜀主徙镇江军治夔州。；核对说明：迁的是镇江军军治，不推为全境迁移。", "status": "draft", "id": "c28c0c9d-1981-592b-be64-ec7a72069ff9", "subject_id": "4b10d3aa-21f6-5922-b3f5-2ce7f2189d77", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "914年四月丙子", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p006·原文件第17行", "note": "原文：夏，四月，丙子，蜀主徙镇江军治夔州。；核对说明：沿主书段落次序；干支日未换算公历日。", "status": "draft", "id": "6c975da1-8023-5d78-9c0b-1b77089e7cd8", "subject_id": "4b10d3aa-21f6-5922-b3f5-2ce7f2189d77", "source_id": "304a11bc-6cb3-5bcb-bd68-5905a70b76b0"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记王建：迁镇江军治于夔州的前蜀皇帝。", "citation": "卷269·乾化四年（914）·zztj-v269-y0914-p006·原文件第17行", "note": "原文：夏，四月，丙子，蜀主徙镇江军治夔州。；核对说明：只据本段确认身份；繁简字形用于匹配，原文仍保持底本原字。", "status": "